16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.time.Month;
23	import java.time.Period;
24	import java.util.Map;
25	
26	/**
27	 * Pure derivations of an {@link Owner}'s read-only attributes.
28	 *
29	 * <p>Each method computes one derived value from an owner's own field values and
30	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
31	 * exposes these through thin {@code @Transient} getters that pass in the relevant
32	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
33	 * to describe its persistent state and relationships while its growing family of
34	 * derived attributes lives together in one place.
35	 */
36	final class OwnerDerivations {
37	
38	    /** Fixed city-to-region table used to derive {@link #region}. */
39	    private static final Map<String, String> CITY_REGION = Map.of(
40	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
41	
42	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
43	     *  {@link #region} in preference to the city. */
44	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
45	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
46	
47	    /** Fixed region-to-timezone table (IANA names) used to derive {@link #timezone}. */
48	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
49	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
50	
51	    private OwnerDerivations() {
52	    }
53	
54	    /**
55	     * The owner's locality, i.e. the canonical region it belongs to. This is read
56	     * from the region-and-hash {@code customerCode} identity: the region is the
57	     * {@code <REGION>} component that precedes the first {@code '-'} of the assigned
58	     * customer code (e.g. {@code NSW} for {@code NSW-9F86D081}). Until an owner has
59	     * been assigned a customer code (for example while its create request is still
60	     * being validated) this falls back to the region derived directly from its own
61	     * fields (see {@link #region(String, String)}).
62	     *
63	     * @return the canonical region string, or {@code "UNKNOWN"}
64	     */
65	    static String locality(String customerCode, String postcode, String city) {
66	        if (customerCode != null) {
67	            int dash = customerCode.indexOf('-');
68	            if (dash >= 0) {
69	                return customerCode.substring(0, dash);
70	            }
71	        }
72	        return region(postcode, city);
73	    }
74	
75	    /**
76	     * The canonical region derived for an owner from its own fields. The postcode is
77	     * consulted first: when it is present and falls within a known region's inclusive
78	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
79	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
80	     * known range does this fall back to the fixed city-to-region table
81	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
82	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
83	     * the same region for the known cities while disambiguating cities that share a name
84	     * via their postcode.
85	     *
86	     * @return the canonical region string, or {@code "UNKNOWN"}
87	     */
88	    static String region(String postcode, String city) {
89	        String byPostcode = regionForPostcode(postcode);
90	        if (byPostcode != null) {
91	            return byPostcode;
92	        }
93	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
94	    }
95	
96	    /**
97	     * The IANA timezone name derived from the given {@code locality} (a canonical
98	     * region) via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
99	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
100	     * {@code null} when the locality is not one of the known regions (for example
101	     * {@code "UNKNOWN"}).
102	     *
103	     * @return the IANA timezone name, or {@code null}
104	     */
105	    static String timezone(String locality) {
106	        return REGION_TIMEZONE.get(locality);
107	    }
108	
109	    /**
110	     * The region whose inclusive postcode range contains the given postcode, or
111	     * {@code null} when the postcode is absent, not a four-digit number, or in no
112	     * known range.
113	     */
114	    private static String regionForPostcode(String postcode) {
115	        if (postcode == null || !postcode.matches("\\d{4}")) {
116	            return null;
117	        }
118	        int value = Integer.parseInt(postcode);
119	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
120	            int[] range = entry.getValue();
121	            if (value >= range[0] && value <= range[1]) {
122	                return entry.getKey();
123	            }
124	        }
125	        return null;
126	    }
127	
128	    /**
129	     * Whether the given {@code postcode} is acceptable for the given {@code region}: an
130	     * absent postcode is always accepted, a present postcode must be exactly four
131	     * digits and, when the region has a known inclusive postcode range
132	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), fall within
133	     * it. A region with no known range (for example {@code "UNKNOWN"}) accepts any
134	     * four-digit postcode.
135	     *
136	     * @return {@code true} if the postcode is absent or valid for the region
137	     */
138	    static boolean postcodeMatchesRegion(String postcode, String region) {
139	        if (postcode == null) {
140	            return true;
141	        }
142	        if (!postcode.matches("\\d{4}")) {
143	            return false;
144	        }
145	        int[] range = REGION_POSTCODES.get(region);
146	        if (range == null) {
147	            return true;
148	        }
149	        int value = Integer.parseInt(postcode);
150	        return value >= range[0] && value <= range[1];
151	    }
152	
153	    /**
154	     * The owner's membership points, a non-negative score derived from its factors:
155	     * starting at 0, add 2 when an {@code email} is present, add 1 when
156	     * {@code namesakeCount} is 0, add 2 for a household of 3 or more (its
157	     * {@code householdSize}) and add 3 when the owner's tenure exceeds a year, measured as
158	     * the number of whole fiscal years elapsed from its {@code registrationDate} up to
159	     * {@code asOf} (the fiscal year starts on 1 July). Because a newly created owner has
160	     * zero elapsed fiscal years, it never earns the tenure points at creation.
161	     *
162	     * @return the membership points, 0 or more
163	     */
164	    static int membershipPoints(String email, Integer namesakeCount, Integer householdSize,
165	            LocalDate registrationDate, LocalDate asOf) {
166	        int points = 0;
167	        if (hasEmail(email)) {
168	            points += 2;
169	        }
170	        if (namesakeCount != null && namesakeCount == 0) {
171	            points += 1;
172	        }
173	        if (householdSize != null && householdSize >= 3) {
174	            points += 2;
175	        }
176	        if (tenureExceedsYear(registrationDate, asOf)) {
177	            points += 3;
178	        }
179	        return points;
180	    }
181	
182	    /**
183	     * The owner's membership level, a number from 1 to 4, mapped from its
184	     * {@link #membershipPoints(String, Integer, Integer, LocalDate, LocalDate) membership
185	     * points}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5 and level 4 for 6
186	     * or more.
187	     *
188	     * @return the membership level, from 1 to 4
189	     */
190	    static int membershipLevel(int points) {
191	        if (points <= 1) {
192	            return 1;
193	        }
194	        if (points <= 3) {
195	            return 2;
196	        }
197	        if (points <= 5) {
198	            return 3;
199	        }
200	        return 4;
201	    }
202	
203	    /**
204	     * The owner's membership level after applying its household level ceiling. The level
205	     * mapped from {@code points} (see {@link #membershipLevel(int)}) is returned unchanged
206	     * when {@code cap} is {@code null} (the owner joined no existing household), and
207	     * otherwise capped to at most {@code cap} — the ceiling assigned at creation, one above
208	     * the highest level then held by an existing household member — so a new owner can rise
209	     * to at most one level above its household.
210	     *
211	     * @return the capped membership level, from 1 to 4
212	     */
213	    static int membershipLevel(int points, Integer cap) {
214	        int level = membershipLevel(points);
215	        return cap == null ? level : Math.min(level, cap);
216	    }
217	
218	    /**
219	     * The owner's marketing segment, formatted {@code <TIER>_<AREA>}, one of
220	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
221	     * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when {@code membershipLevel} is 3
222	     * or more, otherwise {@code STANDARD}. AREA is {@code METRO} when {@code locality} is a
223	     * known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code REGIONAL}.
224	     *
225	     * @return the owner's segment as {@code <TIER>_<AREA>}
226	     */
227	    static String ownerSegment(int membershipLevel, String locality) {
228	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
229	        String area = REGION_TIMEZONE.containsKey(locality) ? "METRO" : "REGIONAL";
230	        return tier + "_" + area;
231	    }
232	
233	    /**
234	     * Whether the owner's tenure exceeds a year, i.e. at least one whole fiscal year has
235	     * elapsed from its {@code registrationDate} up to {@code asOf} (see
236	     * {@link #elapsedFiscalYears(LocalDate, LocalDate)}). This is the single tenure test
237	     * the tenure-driven membership derivations share, so they agree on exactly when an
238	     * owner has been a member for "over a year"; it is {@code false} whenever either date
239	     * is absent.
240	     */
241	    private static boolean tenureExceedsYear(LocalDate registrationDate, LocalDate asOf) {
242	        return registrationDate != null && asOf != null
243	            && elapsedFiscalYears(registrationDate, asOf) >= 1;
244	    }
245	
246	    /**
247	     * The number of whole fiscal years elapsed from {@code registrationDate} up to
248	     * {@code asOf}, i.e. the difference between the fiscal year that contains {@code asOf}
249	     * and the one that contains {@code registrationDate} (see {@link #fiscalYearOf(LocalDate)}).
250	     * Two dates in the same fiscal year yield {@code 0}, so an owner registered in the
251	     * current fiscal year has zero tenure until the next 1 July rollover.
252	     */
253	    static int elapsedFiscalYears(LocalDate registrationDate, LocalDate asOf) {
254	        return fiscalYearOf(asOf) - fiscalYearOf(registrationDate);
255	    }
256	
257	    /**
258	     * The fiscal year that contains the given date, as a four-digit calendar year. The
259	     * fiscal year runs from 1 July to 30 June and is labelled by the calendar year in
260	     * which it ends: a date from January to June falls in the fiscal year of its own
261	     * calendar year, while a date from July to December falls in the next calendar year's
262	     * fiscal year (e.g. {@code 2026-05-03 -> 2026} but {@code 2026-08-03 -> 2027}).
263	     */
264	    static int fiscalYearOf(LocalDate date) {
265	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
266	    }
267	
268	    /**
269	     * The owner's fiscal year, formatted {@code FY<YY>} where YY is the last two digits of
270	     * the fiscal year (see {@link #fiscalYearOf(LocalDate)}) that contains its
271	     * business-day-adjusted {@code registrationDate}, e.g. {@code FY27} for a registration
272	     * date of {@code 2026-08-03}. Returns {@code null} when no registration date is present.
273	     *
274	     * @return the fiscal year as {@code FY<YY>}, or {@code null}
275	     */
276	    static String fiscalYear(LocalDate registrationDate) {
277	        if (registrationDate == null) {
278	            return null;
279	        }
280	        return String.format("FY%02d", fiscalYearOf(registrationDate) % 100);
281	    }
282	
283	    /**
284	     * The owner's salutation, formed as {@code title + ' ' + lastName} when a
285	     * {@code title} is present, or just the {@code lastName} when no title is supplied.
286	     * A {@code null} or blank title contributes nothing, yielding the bare last name.
287	     *
288	     * @return the composed salutation
289	     */
290	    static String salutation(String title, String lastName) {
291	        if (title == null || title.isBlank()) {
292	            return lastName;
293	        }
294	        return title + " " + lastName;
295	    }
296	
297	    /**
298	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
299	     * is present, otherwise {@code "PHONE"}.
300	     *
301	     * @return {@code "EMAIL"} or {@code "PHONE"}
302	     */
303	    static String contactPreference(String email) {
304	        if (hasEmail(email)) {
305	            return "EMAIL";
306	        }
307	        return "PHONE";
308	    }
309	
310	    /**
311	     * Whether the owner has an email address on file, i.e. its {@code email} is present
312	     * and not blank. This is the single presence test the email-driven derivations share
313	     * (a membership-level factor and the {@link #contactPreference(String) contact
314	     * preference}), so they agree on exactly what counts as "has an email".
315	     */
316	    private static boolean hasEmail(String email) {
317	        return email != null && !email.isBlank();
318	    }
319	
320	    /**
321	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
322	     * given {@code customerCode}, processed right-to-left with every second digit
323	     * doubled (and reduced by 9 when the double exceeds 9). Non-digit characters are
324	     * ignored, and an absent or digit-free customer code yields {@code 0}.
325	     *
326	     * @return the Luhn check digit, from 0 to 9
327	     */
328	    static int checkDigit(String customerCode) {
329	        int sum = 0;
330	        boolean doubleDigit = true;
331	        for (int i = (customerCode == null ? 0 : customerCode.length()) - 1; i >= 0; i--) {
332	            char c = customerCode.charAt(i);
333	            if (c < '0' || c > '9') {
334	                continue;
335	            }
336	            int d = c - '0';
337	            if (doubleDigit) {
338	                d *= 2;
339	                if (d > 9) {
340	                    d -= 9;
341	                }
342	            }
343	            sum += d;
344	            doubleDigit = !doubleDigit;
345	        }
346	        return (10 - (sum % 10)) % 10;
347	    }
348	
349	    /**
350	     * The owner's age band, derived from its {@code birthDate} measured against its
351	     * {@code registrationDate}: {@code "MINOR"} when the owner is under 18 on the
352	     * registration date, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
353	     * over. The age is the number of whole years between the two dates. Returns
354	     * {@code null} when either date is absent, so no band is reported for an owner
355	     * without a supplied birth date.
356	     *
357	     * @return {@code "MINOR"}, {@code "ADULT"}, {@code "SENIOR"}, or {@code null}
358	     */
359	    static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
360	        if (birthDate == null || registrationDate == null) {
361	            return null;
362	        }
363	        int age = Period.between(birthDate, registrationDate).getYears();
364	        if (age < 18) {
365	            return "MINOR";
366	        }
367	        if (age < 65) {
368	            return "ADULT";
369	        }
370	        return "SENIOR";
371	    }
372	
373	    /**
374	     * The single derived key used for duplicate detection: the lower-case hexadecimal
375	     * SHA-256 digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
376	     * soundex(lastName)}. The telephone is the owner's stored (E.164-normalised)
377	     * telephone (or the empty string when absent), the email is the stored (lower-cased)
378	     * email or the empty string when absent, and the last-name component is the
379	     * {@link #soundex(String) Soundex code} of the owner's last name. Because the
380	     * telephone is part of the key, two owners sharing a last name and postcode but with
381	     * different telephones have different keys.
382	     *
383	     * @return the owner's identity key, a 64-character lower-case hex string
384	     */
385	    static String identityKey(String telephone, String email, String lastName) {
386	        String tel = telephone == null ? "" : telephone;
387	        String mail = email == null ? "" : email.toLowerCase();
388	        return sha256Hex(tel + "|" + mail + "|" + soundex(lastName));
389	    }
390	
391	    /**
392	     * The American Soundex code of the given name: its first letter followed by three
393	     * digits derived from the remaining consonants ({@code b,f,p,v -> 1};
394	     * {@code c,g,j,k,q,s,x,z -> 2}; {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5};
395	     * {@code r -> 6}), where adjacent letters mapping to the same digit (including when
396	     * separated only by {@code h} or {@code w}) are coded once, vowels ({@code a,e,i,o,u},
397	     * and {@code y}) separate otherwise-identical digits, and the result is zero-padded or
398	     * truncated to exactly four characters. Non-letters are ignored; an absent or
399	     * letter-free value yields the empty string.
400	     *
401	     * @param value the name to encode (may be {@code null})
402	     * @return the four-character Soundex code, or the empty string
403	     */
404	    static String soundex(String value) {
405	        if (value == null) {
406	            return "";
407	        }
408	        StringBuilder letters = new StringBuilder();
409	        for (char c : value.toUpperCase().toCharArray()) {
410	            if (c >= 'A' && c <= 'Z') {
411	                letters.append(c);
412	            }
413	        }
414	        if (letters.length() == 0) {
415	            return "";
416	        }
417	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
418	        char previousDigit = soundexDigit(letters.charAt(0));
419	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
420	            char letter = letters.charAt(i);
421	            char digit = soundexDigit(letter);
422	            if (digit != '0' && digit != previousDigit) {
423	                code.append(digit);
424	            }
425	            if (letter != 'H' && letter != 'W') {
426	                previousDigit = digit;
427	            }
428	        }
429	        while (code.length() < 4) {
430	            code.append('0');
431	        }
432	        return code.toString();
433	    }
434	
435	    /**
436	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a letter that
437	     * carries no Soundex digit (the vowels {@code a,e,i,o,u}, and {@code y,h,w}).
438	     */
439	    private static char soundexDigit(char c) {
440	        return switch (c) {
441	            case 'B', 'F', 'P', 'V' -> '1';
442	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
443	            case 'D', 'T' -> '3';
444	            case 'L' -> '4';
445	            case 'M', 'N' -> '5';
446	            case 'R' -> '6';
447	            default -> '0';
448	        };
449	    }
450	
451	    /**
452	     * The owner's customer code, formatted {@code <REGION>-<HASH8>}: {@code region} is
453	     * the owner's canonical region (see {@link #region(String, String)}) and HASH8 is the
454	     * first eight upper-case hexadecimal characters of the SHA-256 digest of the owner's
455	     * normalised telephone concatenated with its last name (e.g. {@code NSW-9F86D081}).
456	     *
457	     * @return the customer code
458	     */
459	    static String customerCode(String region, String telephone, String lastName) {
460	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8).toUpperCase();
461	        return String.format("%s-%s", region, hash8);
462	    }
463	
464	    /**
465	     * The owner's membership number, formatted {@code <customerCode>-M<YY>}: the owner's
466	     * already-assigned {@code customerCode} followed by {@code -M} and the two-digit fiscal
467	     * year segment derived from its {@code registrationDate} (the last two digits of the
468	     * fiscal year that contains that date; see {@link #fiscalYearOf(LocalDate)}), e.g.
469	     * {@code NSW-9F86D081-M27} for a registration date of {@code 2026-08-03}. Derived from
470	     * the customer code and registration date once both have been assigned, so it lives with
471	     * the other owner derivations rather than in the controller that assigns it.
472	     *
473	     * @return the membership number
474	     */
475	    static String membershipNumber(String customerCode, LocalDate registrationDate) {
476	        int yy = fiscalYearOf(registrationDate) % 100;
477	        return String.format("%s-M%02d", customerCode, yy);
478	    }
479	
480	    /**
481	     * The stable identifier for the household an owner belongs to, derived
482	     * deterministically from its {@code normalizedLastName} and {@code postcode} so that
483	     * every owner sharing a last name and postcode resolves to the same value. It is the
484	     * first twelve lower-case hexadecimal characters of the SHA-256 digest of
485	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes the
486	     * empty string).
487	     *
488	     * @return the household identifier
489	     */
490	    static String householdId(String normalizedLastName, String postcode) {
491	        String pc = postcode == null ? "" : postcode;
492	        return sha256Hex(normalizedLastName + "|" + pc).substring(0, 12);
493	    }
494	
495	    /**
496	     * Reduce an address to its canonical stored form: trim and collapse runs of
497	     * whitespace to a single space, upper-case, and expand common abbreviations
498	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
499	     * they appear as whole words. The result is what is stored, returned and used
500	     * for every household comparison; it is idempotent, so re-normalising an
501	     * already-normalised address leaves it unchanged.
502	     *
503	     * @param value the raw address (may be {@code null})
504	     * @return the normalised address, or the empty string if {@code value} is
505	     *         {@code null} or blank
506	     */
507	    static String normalizeAddress(String value) {
508	        String collapsed = collapseWhitespace(value).toUpperCase();
509	        if (collapsed.isEmpty()) {
510	            return "";
511	        }
512	        String[] tokens = collapsed.split(" ");
513	        for (int i = 0; i < tokens.length; i++) {
514	            tokens[i] = switch (tokens[i]) {
515	                case "ST" -> "STREET";
516	                case "RD" -> "ROAD";
517	                case "AVE" -> "AVENUE";
518	                default -> tokens[i];
519	            };
520	        }
521	        return String.join(" ", tokens);
522	    }
523	
524	    /**
525	     * Trim the given value and collapse every internal run of whitespace to a single
526	     * space, treating an absent value as empty. This is the single whitespace
527	     * normalisation the name and address normalisers share, so they agree on what
528	     * counts as insignificant whitespace; each then applies its own casing (and, for
529	     * addresses, whole-word abbreviation expansion).
530	     *
531	     * @param value the raw value (may be {@code null})
532	     * @return the trimmed, whitespace-collapsed value, or the empty string when
533	     *         {@code value} is {@code null}
534	     */
535	    static String collapseWhitespace(String value) {
536	        if (value == null) {
537	            return "";
538	        }
539	        return value.trim().replaceAll("\\s+", " ");
540	    }
541	
542	    /**
543	     * The SHA-256 digest of the UTF-8 bytes of the given value, as a lower-case
544	     * hexadecimal string. Callers take the prefix and case they need.
545	     */
546	    static String sha256Hex(String value) {
547	        try {
548	            byte[] digest = MessageDigest.getInstance("SHA-256")
549	                .digest(value.getBytes(StandardCharsets.UTF_8));
550	            StringBuilder hex = new StringBuilder(digest.length * 2);
551	            for (byte b : digest) {
552	                hex.append(String.format("%02x", b));
553	            }
554	            return hex.toString();
555	        } catch (NoSuchAlgorithmException e) {
556	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
557	        }
558	    }
