479	    /**
480	     * The American Soundex code of the given name. This is the last-name comparison used
481	     * by both the identity key and the soft-match duplicate check; see
482	     * {@link OwnerDerivations#soundex(String)} for the exact algorithm.
483	     *
484	     * @param value the name to encode (may be {@code null})
485	     * @return the four-character Soundex code, or the empty string
486	     */
487	    public static String soundex(String value) {
488	        return OwnerDerivations.soundex(value);
489	    }
490	
491	    /**
492	     * Compute the customer code to assign to this owner at creation, formatted
493	     * {@code <REGION>-<HASH8>} from the owner's (already normalised) fields. This is the
494	     * value stored in {@link #getCustomerCode()}; see
495	     * {@link OwnerDerivations#customerCode(String, String, String)} for the format.
496	     *
497	     * @return the customer code to assign
498	     */
499	    public String computeCustomerCode() {
500	        return OwnerDerivations.customerCode(regionForOwner(), this.telephone, this.getLastName());
501	    }
502	
503	    /**
504	     * Compute the membership number to assign to this owner at creation, formatted
505	     * {@code <customerCode>-M<YY>} from its already-assigned customer code and registration
506	     * date. This is the value stored in {@link #getMembershipNumber()}; see
507	     * {@link OwnerDerivations#membershipNumber(String, LocalDate)} for the exact format.
508	     *
509	     * @return the membership number to assign
510	     */
511	    public String computeMembershipNumber() {
512	        return OwnerDerivations.membershipNumber(this.customerCode, this.registrationDate);
513	    }
514	
515	    /**
516	     * Compute the stable household identifier for this owner, derived deterministically
517	     * from its last name and postcode so every owner sharing a last name and postcode
518	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
519	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
520	     *
521	     * @return the household identifier
522	     */
523	    public String computeHouseholdId() {
524	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
525	    }
526	
527	    /**
528	     * Whether this owner belongs to the same household as {@code other}: that is, they
529	     * share the same last name and postcode. The last name is compared
530	     * case-insensitively with runs of whitespace collapsed to a single space (and
531	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
532	     * absent postcodes count as equal). Owners in the same household resolve to the same
533	     * {@link #computeHouseholdId() household identifier}.
534	     *
535	     * @param other the owner to compare against
536	     * @return {@code true} if both owners share a household
537	     */
538	    public boolean sameHouseholdAs(Owner other) {
539	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
540	            && Objects.equals(this.postcode, other.postcode);
541	    }
542	
543	    /**
544	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
545	     * trim, collapse internal runs of whitespace to a single space and lower-case.
546	     */
547	    private static String normalize(String value) {
548	        return OwnerDerivations.collapseWhitespace(value).toLowerCase();
549	    }
550	
551	    /**
552	     * Reduce an address to its canonical stored form. This is the value stored,
553	     * returned and used for every household comparison; see
554	     * {@link OwnerDerivations#normalizeAddress(String)} for the exact normalisation.
555	     *
556	     * @param value the raw address (may be {@code null})
557	     * @return the normalised address, or the empty string if {@code value} is
558	     *         {@code null} or blank
559	     */
560	    public static String normalizeAddress(String value) {
561	        return OwnerDerivations.normalizeAddress(value);
562	    }
563	
564	    protected Set<Pet> getPetsInternal() {
565	        if (this.pets == null) {
566	            this.pets = new HashSet<>();
567	        }
568	        return this.pets;
569	    }
570	
571	    protected void setPetsInternal(Set<Pet> pets) {
572	        this.pets = pets;
573	    }
574	
575	    public List<Pet> getPets() {
576	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
577	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
578	        return Collections.unmodifiableList(sortedPets);
579	    }
580	
581	    public void setPets(List<Pet> pets) {
582	        this.pets = new HashSet<>(pets);
583	    }
584	
585	    public void addPet(Pet pet) {
586	        getPetsInternal().add(pet);
587	        pet.setOwner(this);
588	    }
589	
590	    /**
591	     * Return the Pet with the given name, or null if none found for this Owner.
592	     *
593	     * @param name to test
594	     * @return true if pet name is already in use
595	     */
596	    public Pet getPet(String name) {
597	        return getPet(name, false);
598	    }
599	
600	    /**
601	     * Return the Pet with the given name, or null if none found for this Owner.
602	     *
603	     * @param name to test
604	     * @return true if pet name is already in use
605	     */
606	    public Pet getPet(String name, boolean ignoreNew) {
607	        name = name.toLowerCase();
608	        for (Pet pet : getPetsInternal()) {
609	            if (!ignoreNew || !pet.isNew()) {
610	                String compName = pet.getName();
611	                compName = compName.toLowerCase();
612	                if (compName.equals(name)) {
613	                    return pet;
614	                }
615	            }
616	        }
617	        return null;
618	    }
619	
620	    public Pet getPet(Integer petId) {
621	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
622	    }
623	
624	    @Override
625	    public String toString() {
626	        return new ToStringCreator(this)
627	
628	            .append("id", this.getId())
629	            .append("new", this.isNew())
630	            .append("lastName", this.getLastName())
631	            .append("firstName", this.getFirstName())
632	            .append("address", this.address)
633	            .append("city", this.city)
634	            .append("telephone", this.telephone)
635	            .toString();
636	    }
637	}
