371	    /**
372	     * Email domains that identify disposable, throw-away mailboxes. An owner whose
373	     * email address is on one of these domains is rejected with {@code 400 Bad
374	     * Request} rather than created.
375	     */
376	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
377	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
378	
379	    /**
380	     * Whether the given (already lower-cased) email address belongs to a disposable
381	     * mailbox domain on the blocklist. The domain is the part after the final
382	     * {@code '@'}; an address without one is treated as having no blocked domain.
383	     *
384	     * @param email the owner's normalised (lower-cased) email address
385	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
386	     */
387	    private static boolean emailDomainIsBlocked(String email) {
388	        int at = email.lastIndexOf('@');
389	        if (at < 0) {
390	            return false;
391	        }
392	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
393	    }
394	
395	    /**
396	     * The fixed list of public holidays on which the clinic is closed. A registration
397	     * date that lands on one of these dates is treated the same as a weekend and rolled
398	     * forward past it (see {@link #rollToBusinessDay(LocalDate)}).
399	     */
400	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
401	        LocalDate.of(2026, 1, 1),
402	        LocalDate.of(2026, 1, 26),
403	        LocalDate.of(2026, 4, 25),
404	        LocalDate.of(2026, 12, 25),
405	        LocalDate.of(2026, 12, 28));
406	
407	    /**
408	     * Roll the given date forward to the next business day when it falls on a weekend or
409	     * a listed public holiday: a Saturday, Sunday or public holiday is advanced one day
410	     * at a time until a non-holiday weekday is reached, while a plain business day is
411	     * returned unchanged. Because rolling off a weekend can land on a holiday (and vice
412	     * versa), the advance repeats until the date is neither. Applied to the effective
413	     * registration date (whether supplied in the request or defaulted to the server date)
414	     * so that every value derived from it uses the adjusted business day.
415	     *
416	     * @param date the effective registration date
417	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
418	     */
419	    private static LocalDate rollToBusinessDay(LocalDate date) {
420	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
421	            date = date.plusDays(1);
422	        }
423	        return date;
424	    }
425	
426	    /**
427	     * Whether the given date falls on a weekend (Saturday or Sunday).
428	     */
429	    private static boolean isWeekend(LocalDate date) {
430	        return switch (date.getDayOfWeek()) {
431	            case SATURDAY, SUNDAY -> true;
432	            default -> false;
433	        };
434	    }
435	
436	    /**
437	     * Find the existing owners that belong to the same household as the given owner,
438	     * i.e. share the same last name (compared case-insensitively with runs of
439	     * whitespace collapsed to a single space) and postcode, and so resolve to the same
440	     * deterministic {@code householdId}. Soft-deleted owners are excluded, so the result
441	     * holds only current household members. Evaluated before the new owner is saved, so
442	     * it reflects only owners that already existed at creation time; an owner joining no
443	     * existing household yields an empty list.
444	     *
445	     * @param owner the candidate owner being created
446	     * @return the current members of the owner's household, empty if none exists
447	     */
448	    private List<Owner> findHouseholdMembers(Owner owner) {
449	        return activeOwners()
450	            .filter(existing -> existing.sameHouseholdAs(owner))
451	            .toList();
452	    }
453	
454	    /**
455	     * Whether the candidate owner is a hard duplicate of an existing owner, i.e. it shares
456	     * the {@link Owner#getIdentityKey() identity key} (the SHA-256 digest over its
457	     * normalised telephone, lower-cased email and the Soundex of its last name) of a
458	     * current owner. Soft-deleted owners are ignored, so only the current owner population
459	     * is considered. A create whose identity key collides with an existing owner is
460	     * rejected with {@code 409 Conflict}. Evaluated after normalisation (so the
461	     * email-domain blocklist has already been applied) and before the owner is saved.
462	     *
463	     * @param owner the candidate owner being created, after normalisation
464	     * @return {@code true} if an existing, non-deleted owner shares the candidate's
465	     *         identity key
466	     */
467	    private boolean isDuplicateIdentity(Owner owner) {
468	        String identityKey = owner.getIdentityKey();
469	        return activeOwners()
470	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
471	    }
472	
473	    /**
474	     * The existing owners that are still active, i.e. those not flagged as soft-deleted.
475	     * Evaluated fresh against the saved owners each call, so it reflects only owners that
476	     * already existed at creation time; a soft-deleted owner is excluded and so takes no
477	     * part in the household resolution built on top of it. Isolating the exclusion here
478	     * keeps the "current owner population" one candidate is compared against in one place.
479	     *
480	     * @return a stream of the current, non-deleted owners
481	     */
482	    private Stream<Owner> activeOwners() {
483	        return this.clinicService.findAllOwners().stream()
484	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
485	    }
486	
487	    /**
488	     * Assign the owner's computed-at-creation attributes in place: its customer code,
489	     * namesake count, membership number, bulk-signup warning and household size. Unlike
490	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
491	     * derived once here — from the owner's own (already normalised) fields and from the
492	     * wider owner population — and persisted with the owner. Run after normalisation,
493	     * household resolution and the identity-key check, so every value reflects the
494	     * owner's final field values and any household it has joined, and immediately before
495	     * the owner is saved.
496	     *
497	     * <p>Ordering matters: the customer code is assigned first because the membership
498	     * number is built from it.
499	     *
500	     * @param owner the candidate owner being created, after household resolution
501	     * @param declaredHouseholdMember whether this owner was created as a declared member
502	     *                                of an existing household (it shared an existing
503	     *                                owner's household and set {@code sharesHousehold}),
504	     *                                in which case it is not a suspected duplicate
505	     * @param householdMembers        the existing members of the owner's household at
506	     *                                creation time, used to derive its level ceiling
507	     */
508	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember,
509	            List<Owner> householdMembers) {
510	        owner.setCustomerCode(deduplicatedCustomerCode(owner));
511	        owner.setNamesakeCount(countNamesakes(owner));
512	        owner.setMembershipNumber(owner.computeMembershipNumber());
513	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
514	        owner.setCapacityWarning(cityApproachingCapacity(owner.getCity()));
515	        owner.setHouseholdSize(householdSize(owner));
516	        owner.setMembershipLevelCap(membershipLevelCap(householdMembers));
517	        assignPossibleDuplicate(owner, declaredHouseholdMember);
518	    }
519	
520	    /**
521	     * The household level ceiling to assign to the candidate owner: one above the highest
522	     * {@link Owner#getMembershipLevel() membership level} currently held by an existing
523	     * member of its household, or {@code null} when the household has no existing member
524	     * (so no ceiling applies). This bounds a new owner's reported membership level to at
525	     * most one above its household, keeping households from being outranked at the moment a
526	     * relative joins. Evaluated before the owner is saved, over the members that already
527	     * existed at creation time.
528	     *
529	     * @param householdMembers the existing members of the owner's household
530	     * @return the level ceiling to assign, or {@code null} when uncapped
531	     */
532	    private Integer membershipLevelCap(List<Owner> householdMembers) {
533	        return householdMembers.stream()
534	            .map(Owner::getMembershipLevel)
535	            .max(Comparator.naturalOrder())
536	            .map(max -> max + 1)
537	            .orElse(null);
538	    }
539	
540	    /**
541	     * Compute the customer code to assign to the candidate owner, de-duplicated against
542	     * every existing owner's customer code. The base code is the owner's computed
543	     * {@code <REGION>-<HASH8>} (see {@link Owner#computeCustomerCode()}); when it does not
544	     * already belong to an existing owner it is used unchanged. Otherwise it collides, and
545	     * {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that yields
546	     * a code no existing owner holds, so the returned customer code is unique. Evaluated
547	     * before the owner is saved, so only pre-existing owners are considered.
548	     *
549	     * @param owner the candidate owner being created, after normalisation
550	     * @return the unique (de-duplicated) customer code to assign
551	     */
552	    private String deduplicatedCustomerCode(Owner owner) {
553	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
554	            .map(Owner::getCustomerCode)
555	            .filter(code -> code != null)
556	            .collect(java.util.stream.Collectors.toSet());
557	        String base = owner.computeCustomerCode();
558	        if (!existingCodes.contains(base)) {
559	            return base;
560	        }
561	        int n = 2;
562	        while (existingCodes.contains(base + "-" + n)) {
563	            n++;
564	        }
565	        return base + "-" + n;
566	    }
567	
568	    /**
569	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
570	     * match is an existing owner that shares this owner's last name (compared
571	     * case-insensitively) and postcode but carries a different (normalised) telephone.
572	     * When such a match exists the owner is still created, but with
573	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
574	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
575	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
576	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
577	     * are considered.
578	     *
579	     * <p>A declared household member — one that shared an existing owner's household
580	     * (same last name and postcode) and was admitted because it set
581	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
582	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
583	     *
584	     * @param owner the candidate owner being created, after household resolution
585	     * @param declaredHouseholdMember whether the owner is a declared household member
586	     */
587	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
588	        if (declaredHouseholdMember) {
589	            owner.setPossibleDuplicate(false);
590	            owner.setPossibleDuplicateOf(null);
591	            return;
592	        }
593	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
594	            .filter(existing -> isSoftMatch(owner, existing))
595	            .min(Comparator.comparing(Owner::getId));
596	        if (match.isPresent()) {
597	            owner.setPossibleDuplicate(true);
598	            owner.setPossibleDuplicateOf(match.get().getId());
599	        } else {
600	            owner.setPossibleDuplicate(false);
601	            owner.setPossibleDuplicateOf(null);
602	        }
603	    }
604	
605	    /**
606	     * Whether an already-created {@code existing} owner is a soft-match for the candidate
607	     * {@code owner}: their {@link Owner#getIdentityKey() identity keys} differ (so they are
608	     * not a hard duplicate) yet the {@link Owner#soundex(String) Soundex} of their last
609	     * names and their postcodes match. This is the single soft-match test
610	     * {@link #assignPossibleDuplicate} applies across the owner population, isolated here so
611	     * the comparison that decides a suspected duplicate lives in one place. Two owners
612	     * sharing a last name and postcode but with different telephones therefore soft-match
613	     * rather than being rejected, since the telephone is part of the identity key.
614	     *
615	     * @param owner    the candidate owner being created
616	     * @param existing an already-created owner to test against it
617	     * @return {@code true} if {@code existing} is a soft-match for the candidate
618	     */
619	    private boolean isSoftMatch(Owner owner, Owner existing) {
620	        String postcode = owner.getPostcode();
621	        return postcode != null && postcode.equals(existing.getPostcode())
622	            && Owner.soundex(owner.getLastName()).equals(Owner.soundex(existing.getLastName()))
623	            && !owner.getIdentityKey().equals(existing.getIdentityKey());
624	    }
625	
626	    /**
627	     * Count how many owners belong to the given owner's household once this create
628	     * completes: the owners that already share its deterministic {@code householdId}
629	     * (derived from last name and postcode) plus the owner being created. Evaluated
630	     * after the owner's {@code householdId} has been assigned. An owner whose
631	     * {@code householdId} matches no existing owner is a household of one.
632	     *
633	     * @param owner the candidate owner being created, after household resolution
634	     * @return the household member count after this create (at least {@code 1})
635	     */
636	    private int householdSize(Owner owner) {
637	        String householdId = owner.getHouseholdId();
638	        if (householdId == null) {
639	            return 1;
640	        }
641	        long existing = this.clinicService.findAllOwners().stream()
642	            .filter(other -> householdId.equals(other.getHouseholdId()))
643	            .count();
644	        return (int) existing + 1;
645	    }
646	
647	    /**
648	     * Count the existing owners that share the given owner's first and last name,
649	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
650	     * before the new owner is saved, so the result reflects only owners that
651	     * already existed at creation time.
652	     *
653	     * @param owner the candidate owner being created
654	     * @return the number of existing namesakes
655	     */
656	    private int countNamesakes(Owner owner) {
657	        String firstName = normalizeName(owner.getFirstName());
658	        String lastName = normalizeName(owner.getLastName());
659	        return (int) this.clinicService.findAllOwners().stream()
660	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
661	                && normalizeName(existing.getLastName()).equals(lastName))
662	            .count();
663	    }
664	
665	    private static String normalizeName(String value) {
666	        return value == null ? "" : value.trim().toLowerCase();
667	    }
668	
669	    /**
670	     * Determine whether the given city has already reached its owner capacity, i.e.
671	     * it already contains 50 or more existing owners (compared case-insensitively
672	     * with surrounding whitespace trimmed). A new owner may not be created in a city
673	     * that is at capacity.
674	     *
675	     * @param city the candidate owner's city
676	     * @return {@code true} if the city already holds 50 or more owners
677	     */
678	    private boolean cityIsAtCapacity(String city) {
679	        return ownersInCity(city) >= 50;
680	    }
681	
682	    /**
683	     * Determine whether the given city is approaching its owner capacity, i.e. it
684	     * already contains between 40 and 49 existing owners (compared case-insensitively
685	     * with surrounding whitespace trimmed). This warns that the capacity limit of 50
686	     * is near; the hard rejection at 50 is handled separately by
687	     * {@link #cityIsAtCapacity(String)}. Evaluated before the new owner is saved, so
688	     * it reflects only owners that already existed at creation time.
689	     *
690	     * @param city the candidate owner's city
691	     * @return {@code true} if the city already holds between 40 and 49 owners
692	     */
693	    private boolean cityApproachingCapacity(String city) {
694	        long count = ownersInCity(city);
695	        return count >= 40 && count < 50;
696	    }
697	
698	    /**
699	     * Count the existing owners in the given city, compared case-insensitively with
700	     * surrounding whitespace trimmed.
701	     *
702	     * @param city the city to count owners for
703	     * @return the number of existing owners in that city
704	     */
705	    private long ownersInCity(String city) {
706	        String normalizedCity = normalizeName(city);
707	        return this.clinicService.findAllOwners().stream()
708	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
709	            .count();
710	    }
711	
712	    /**
713	     * Determine whether the daily owner-creation limit has already been reached, i.e.
714	     * 100 or more owners already carry the given registration date. A new owner may
715	     * not be created once that day's cap is reached.
716	     *
717	     * @param registrationDate the registration date the new owner would be created with
718	     * @return {@code true} if 100 or more existing owners share that registration date
719	     */
720	    private boolean dailyLimitReached(LocalDate registrationDate) {
721	        long count = this.clinicService.findAllOwners().stream()
722	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
723	            .count();
724	        return count >= 100;
725	    }
726	
727	    /**
728	     * Determine whether more than 80 owners have already been created for the given
729	     * registration date, i.e. strictly more than 80 existing owners carry that date.
730	     * Evaluated before the new owner is saved, so it reflects only owners that
731	     * already existed at creation time.
732	     *
733	     * @param registrationDate the registration date the new owner would be created with
734	     * @return {@code true} if more than 80 existing owners share that registration date
735	     */
736	    private boolean bulkSignupWarning(LocalDate registrationDate) {
737	        long count = this.clinicService.findAllOwners().stream()
738	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
739	            .count();
740	        return count > 80;
741	    }
742	}
